public sealed class ClockEntryServiceTests
{
    [Fact]
    public void TryCLockIn_WhenNoOpenEntryExists_SavesEntryAndReturnsTrue()
    {
        RecordingClockEntryRepository repository = new();
        ClockEntryService service = new(repository);
        DateTime clockIn = new(2026, 8, 15, 9, 0, 0);

        bool result = service.TryCLockIn(1, clockIn);

        Assert.True(result);
        Assert.Equal(1, repository.SaveCallCount);
        Assert.NotNull(repository.LastSavedEntry);
        Assert.Equal(1, repository.LastSavedEntry.EmployeeId);
        Assert.Equal(clockIn, repository.LastSavedEntry.ClockIn);
    }

    private sealed class RecordingClockEntryRepository : IClockEntryRepository
    {
        public ClockEntry? OpenEntryToReturn { get; set; }
        public ClockEntry? LastSavedEntry { get; private set; }
        public int SaveCallCount { get; private set; }

        public void SaveClockEntry(ClockEntry clockEntry)
        {
            LastSavedEntry = clockEntry;
            SaveCallCount++;
        }

        public IEnumerable<ClockEntry> GetEmployeeClockEntries(int employeeId, DateTime startDate, DateTime endDate)
        {
            return Array.Empty<ClockEntry>();
        }

        public ClockEntry? GetOpenClockEntry(int employeeId)
        {
            return OpenEntryToReturn;
        }
    }
}

using Moq;

public sealed class ClockEntryServiceTests
{
    [Fact]
    public void TryCLockIn_WhenNoOpenEntryExists_VerifiesSaveWithMoq()
    {
        Mock<IClockEntryRepository> repository = new();
        repository.Setup(item => item.GetOpenClockEntry(1))
            .Returns((ClockEntry?)null);
        ClockEntryService service = new(repository.Object);
        DateTime clockIn = new(2026, 8, 15, 9, 0, 0);

        bool result = service.TryCLockIn(1, clockIn);

        Assert.True(result);
        repository.Verify(
            item => item.SaveClockEntry(It.Is<ClockEntry>(entry =>
                entry.EmployeeId == 1 && entry.ClockIn == clockIn)),
            Times.Once);
    }
}
